for name, content in files.items():
    path = out / name
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content)
(out / "package.json").write_text('{"type":"module"}\n')
(out / "NOTICE.txt").write_text("Historical MIT modules: evshiron/parsec-web-client at ddfaeb64c0a54f5ef86ea41a753ad15360a8535c. See LICENSE. Safari adapters, device approval UI and signaling adapter are experimental additions. Current Parsec compatibility is unverified. No proprietary SDK bundle is redistributed.\n")
for path in out.rglob("*.js"):
    subprocess.run(["node", "--input-type=module", "--check"], input=path.read_text(), text=True, check=True)
print("Client generated; all JavaScript modules pass syntax checks")

transport_test = json.loads(r'''"import assert from 'node:assert/strict';\nimport {RTC} from './_site/client/src/rtc.js';\nimport {Signal} from './_site/client/src/signal.js';\nconst offer='v=0\\r\\nm=application 9 UDP/DTLS/SCTP webrtc-datachannel\\r\\na=mid:data\\r\\na=ice-ufrag:local\\r\\na=ice-pwd:local-password\\r\\na=fingerprint:sha-256 AA:BB\\r\\n';\nglobalThis.RTCPeerConnection=class {constructor(){this.candidates=[];}async createOffer(){return {type:'offer',sdp:offer};}createDataChannel(){return {readyState:'open',close(){},send(){}};}async setLocalDescription(d){this.localDescription=d;}async setRemoteDescription(d){this.remoteDescription=d;}async addIceCandidate(c){this.candidates.push(c);}close(){this.closed=true;}};\nlet fatal=null;const transport=new RTC('peer','attempt',()=>{},code=>fatal=code);\nconst creds=await transport.createOffer();assert.equal(creds.ice_ufrag,'local');assert.equal(creds.fingerprint,'sha-256 AA:BB');\nconst remote={ice_ufrag:'remote',ice_pwd:'remote-password',fingerprint:'sha-256 CC:DD'};\ntransport.setCandidate({candidate_ip:'192.0.2.1',candidate_port:5000,sync:0,from_stun:0},remote);\ntransport.setCandidate({candidate_ip:'192.0.2.2',candidate_port:5001,sync:0,from_stun:0},remote);\nawait transport.queue;assert.equal(fatal,null);assert.equal(transport.rtc.candidates.length,2);assert.ok(transport.rtc.remoteDescription.sdp.includes('a=sctp-port:5000\\r\\n'));assert.ok(!transport.rtc.remoteDescription.sdp.includes('undefined'));transport.close();assert.equal(transport.rtc.closed,true);\nglobalThis.WebSocket=class {static OPEN=1;constructor(url,protocol){this.url=url;this.protocol=protocol;this.readyState=1;this.sent=[];}send(data){this.sent.push(JSON.parse(data));}close(){this.closed=true;}};\nlet candidate=null;const signal=new Signal(code=>fatal=code);signal.connect('unused',443,'test-session-not-real','test-peer',creds,(c,k)=>candidate={c,k});const socket=signal.ws;socket.onopen();assert.equal(socket.protocol,'test-session-not-real');assert.equal(socket.sent[0].action,'offer');assert.equal(socket.sent[0].payload.to,'test-peer');assert.ok(!socket.url.includes('test-session-not-real'));\nsocket.onmessage({data:JSON.stringify({action:'candex_relay',payload:{data:{ip:'192.0.2.3',port:5002,sync:0}}})});assert.equal(candidate,null);\nsocket.onmessage({data:JSON.stringify({action:'answer_relay',payload:{approved:true,data:{creds:remote}}})});assert.equal(candidate.c.candidate_port,5002);signal.send('test-session-not-real',{candidate_ip:'192.0.2.4',candidate_port:5003,sync:0,from_stun:0,lan:1});assert.equal(socket.sent[1].action,'candex');assert.equal(socket.sent[1].payload.data.port,5003);signal.connected();signal.close();assert.equal(socket.closed,true);assert.equal(fatal,null);console.log('Offline transport checks passed; live Parsec protocol compatibility remains unverified');\n"''')
subprocess.run(["node", "--input-type=module"], input=transport_test, text=True, check=True)

root_page = Path("_site/index.html")
root_page.write_text(root_page.read_text().replace("<main>", '<main><p><a href="client/">Experimentellen Verbindungsclient öffnen</a></p>', 1))

# Version all module URLs to prevent mixed cached client revisions.
import os
revision = os.environ.get("GITHUB_SHA", "local")[:12]
assets = out / ("assets-" + revision)
assets.mkdir(exist_ok=True)
shutil.move(str(out / "src"), str(assets / "src"))
shutil.move(str(out / "app.js"), str(assets / "app.js"))
page = out / "index.html"
page.write_text(page.read_text().replace('src="app.js"', 'src="assets-' + revision + '/app.js"'))
root_page.write_text(root_page.read_text().replace('href="client/"', 'href="client/?v=' + revision + '"'))
